package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;import com.ruoyi.medical.contracts.*;import com.ruoyi.medical.persistence.mapper.*;
import java.io.IOException;import java.util.*;import javax.sql.DataSource;import org.springframework.jdbc.core.JdbcTemplate;
/** Bounded metadata-only MODEL_VERIFICATION role admission before a lease exists.
 * It authorizes no content read or send; actual reservation/dispatch must revalidate all source use. */
public final class FormalModelVerificationBootstrap {
 private final FormalVerificationJobs jobs;private final FormalCapabilityIdentityAuthority roles;private final PermissionMapper permissions;private final PermissionAuthority grants;private final FormalInvocationSchema schema;private final RunTokenAuthoritySchema runtime;private final JdbcTemplate db;
 public FormalModelVerificationBootstrap(FormalVerificationJobs jobs,FormalCapabilityIdentityAuthority roles,PermissionMapper permissions,PermissionAuthority grants,FormalInvocationSchema schema,RunTokenAuthoritySchema runtime,DataSource data){this.jobs=jobs;this.roles=roles;this.permissions=permissions;this.grants=grants;this.schema=schema;this.runtime=runtime;this.db=new JdbcTemplate(data);db.setQueryTimeout(5);}
 public final class Verified {
  private final List<String> key;private final String digest;private final List<RunTokenAuthoritySchema.Permission> allowed;
  private Verified(List<String> key,String digest,List<RunTokenAuthoritySchema.Permission> allowed){this.key=List.copyOf(key);this.digest=digest;this.allowed=List.copyOf(allowed);}
  public String roleVersion(){return key.get(4);}public String roleRawSha(){return key.get(5);}public List<RunTokenAuthoritySchema.Permission> nodePermissions(){return allowed;}
  public void requireUnchanged()throws IOException{if(!digest.equals(require(key.get(0),key.get(1),key.get(2),key.get(3),key.get(4),key.get(5),key.get(6),key.get(7)).digest))throw new TenantAccessException(ErrorCode.SCOPE_STALE);}
 }
 public Verified require(String tenant,String actor,String run,String step,String roleVersion,String roleRawSha,String serviceUri,String audience)throws IOException{
  try{
   var scope=TenantScope.requireCurrent();if(!tenant.equals(scope.tenantId())||!actor.equals(scope.subjectId())||!org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive())denied();
   var job=jobs.byRun(tenant,run);if(!actor.equals(job.actor())||!run.equals(job.run())||!step.equals(job.step()))denied();
   var request=schema.parse(job.request());var deps=schema.parse(job.dependencies());var basis=new PermissionProtocol.Basis(request.required("role_basis").required("version_id").textValue(),request.required("role_basis").required("content_sha256").textValue());if(!roleVersion.equals(basis.version_id())||!roleRawSha.equals(basis.content_sha256()))bad();
   var identity=roles.requireRegisteredIdentity(tenant,actor,basis,"ROLE",job.project());if(!schema.canonical(identity.canonicalDefinition()).equals(schema.canonical(deps.required("role"))))bad();
   var principal=deps.required("principal");runtime.service(principal,serviceUri,audience);runtime.role(schema.canonical(identity.canonicalDefinition().required("request").required("tool_scope")),principal);var allowed=runtime.permissions(principal);
   var binding=one(permissions.currentBinding(actor));if(!actor.equals(binding.userId())||!"ACTIVE".equals(binding.status()))denied();var now=permissions.databaseTime();var witnesses=new ArrayList<PermissionProtocol.GrantRow>();
   for(var p:allowed){var owner=one(permissions.resourceOwner(p.scope().resource_kind(),p.scope().resource_id()));if(!tenant.equals(p.scope().tenant_id())||!p.scope().resource_id().equals(owner.id())||!Objects.equals(p.scope().project_id(),owner.projectId()))denied();witnesses.add(grants.requireResource(p.scope(),actor,binding.mode(),p.action(),p.purpose(),permissions.resourceGrants(actor,p.action()),now));}
   var original=one(db.query("SELECT request_json,request_sha256,model_revision,config_id,model_sha256,credential_reference_id,credential_revision,grant_id,CAST(grant_revision AS CHAR),operation_id,idempotency_key FROM runtime_connection_intent WHERE tenant_id=? AND verification_id=? AND created_by=? AND project_id=? AND schema_version='1.0.0' AND schema_manifest_sha256=? LIMIT 2",(r,n)->new Original(r.getString(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6),r.getString(7),r.getString(8),r.getString(9),r.getString(10),r.getString(11)),tenant,job.verification(),actor,job.project(),schema.manifestSha256()));
   if(!schema.canonical(schema.parse(original.request())).equals(job.request())||!original.hash().equals(job.requestHash())||!original.model().equals(job.model())||!original.operation().equals(job.operation())||!original.key().equals(job.key())||!original.modelHash().equals(deps.required("model").required("content_sha256").textValue()))bad();
   var configOwner=one(permissions.resourceOwner("CONFIGURATION",original.config()));var grant=grants.requireResource(new PermissionProtocol.Scope(tenant,configOwner.projectId(),"CONFIGURATION",original.config()),actor,binding.mode(),"model.verify","MODEL_VERIFICATION",permissions.resourceGrants(actor,"model.verify"),now);if(!original.grant().equals(grant.grantId())||!original.grantRevision().equals(grant.revision().toString()))throw new TenantAccessException(ErrorCode.SCOPE_STALE);
   int model=one(db.query("SELECT COUNT(*) FROM model_config_revision m JOIN configuration_head h ON h.tenant_id=m.tenant_id AND h.config_id=m.config_id AND h.current_version=m.model_config_revision AND h.execution_mode='EXTERNAL' AND h.kind='MODEL' JOIN version_registry v ON v.tenant_id=m.tenant_id AND v.version_id=m.model_config_revision AND v.entity_kind='MODEL_CONFIG' AND v.content_sha256=m.content_sha256 AND v.owner_project_id <=> m.project_id WHERE m.tenant_id=? AND m.model_config_revision=? AND m.config_id=? AND m.execution_mode='EXTERNAL' AND m.content_sha256=? AND m.credential_reference_id=? AND m.credential_revision=? AND m.status='DRAFT' AND h.status IN ('DRAFT','ACTIVE','PUBLISHED')",(r,n)->r.getInt(1),tenant,original.model(),original.config(),original.modelHash(),original.credential(),original.credentialRevision()));if(model!=1)bad();
   int operation=one(db.query("SELECT COUNT(*) FROM operation_record WHERE tenant_id=? AND operation_id=? AND subject_id=? AND created_by=? AND target_id=? AND operation_name='MODEL-CONNECTION-VERIFICATION' AND idempotency_key=? AND request_sha256=? AND state='PROCESSING' AND schema_version='1.0.0' AND schema_manifest_sha256=?",(r,n)->r.getInt(1),tenant,job.operation(),actor,actor,job.verification(),job.key(),job.requestHash(),schema.manifestSha256()));if(operation!=1)bad();
   return new Verified(List.of(tenant,actor,run,step,roleVersion,roleRawSha,serviceUri,audience),schema.hash(Map.of("job",job,"identity",identity.metadataSha256(),"original",original,"permissions",witnesses,"authority",grant)),allowed);
  }catch(IOException e){throw e;}catch(RuntimeException e){throw e;}catch(Exception e){throw new IOException("Formal verification bootstrap evidence unavailable",e);}
 }
 private record Original(String request,String hash,String model,String config,String modelHash,String credential,String credentialRevision,String grant,String grantRevision,String operation,String key){}
 private static <T>T one(List<T> r){if(r.size()!=1||r.get(0)==null)bad();return r.get(0);}private static void bad(){throw new TenantAccessException(ErrorCode.CONTENT_MISMATCH);}private static void denied(){throw new TenantAccessException(ErrorCode.ACCESS_DENIED);}
}
